import { atom, read, update } from 'claude-code'
import type { EngineInterface as Api, Register, ToolCallResult } from 'claude-code'

import type { Alert, BandState, CoordResult, Family } from '../types'
import { type Lang, type Words, inferLang, pickLang, words } from './i18n'
import {
  type Presence,
  type RepoEntry,
  type Snapshot,
  activeRepos,
  addMarker,
  compactForMidTurn,
  assessAll,
  bandState,
  diffSnapshots,
  dirsInCommand,
  huddleMarker,
  huddleMembers,
  isHostId,
  isLive,
  isSeenSession,
  leadPrompt,
  leaderOf,
  liveHuddle,
  motherOf,
  nameOf,
  newHuddleId,
  normalizeRemote,
  parentFromSession,
  ownerKey,
  ownerOf,
  parseAddMarker,
  parseHuddleMarker,
  parsePorcelain,
  peerMessage,
  reasonOf,
  repoNameOf,
  repoRelative,
  resolvePath,
  sameJson,
  sessionLink,
  shouldPublish,
  sisterNotice,
  shouldRefreshTitle,
  slashes,
  stripMarkers,
  taskFromPrompt,
  upgradePresence,
  FILE_WINDOW_MS,
} from './logic'

const alerts = atom({ plugin: 'huddle', key: 'alerts' } as const, [] as Alert[])
const band = atom({ plugin: 'huddle', key: 'band' } as const, { kind: 'none' } as BandState)
const snoozeUntil = atom({ plugin: 'huddle', key: 'snoozeUntil' } as const, 0)
const lastCoord = atom({ plugin: 'huddle', key: 'lastCoord' } as const, null as CoordResult | null)

const TICK_MS = 15_000
const SNOOZE_MS = 30 * 60_000
const STALE_MS = 24 * 60 * 60_000
const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const HUMAN_ORIGINS = new Set<string>(['composer', 'bridge', 'sdk'])
// The desktop app's own read of a session: its sidebar title. Asked only when it runs without a permission prompt.
const GET_SESSION = 'mcp__ccd_session_mgmt__get_session'
const LEVEL_MARK = { 1: '◦', 2: '▲', 3: '■' } as const
const LEVEL_COLOR = { 1: 'subtle', 2: 'warning', 3: 'error' } as const
// A shell command is watched in at most this many repos; git gets this long to list a repo's dirty files.
const SNAPSHOT_REPOS = 3
const SNAPSHOT_MS = 3000
const STAT_CAP = 300
const NEGATIVE_MS = 60_000
const PENDING_MAX = 5
const LIST_TIMEOUT_MS = 5000
const TOOL_LOOKS_MAX = 12
const ID_RE = /^[A-Za-z0-9_-]{1,80}$/

// The module's own variables: a reload starts them over and session.start fills them again.
let me: Presence | null = null
let dir = ''
let homeDir = ''
let w: Words = words('en')
// What the person's own first prompt read as (Spanish or English), for when no setting says.
let inferred: Lang | null = null
// Peer+repo+level triples already toasted, so an alert is raised once per escalation.
const toasted = new Set<string>()
// Files already toasted as taken by another member of the huddle.
const warned = new Set<string>()
let ticks = 0
// The desktop app's id from the environment. A `claude -p` started from a desktop session inherits it, so it is
// taken as this session's own only once someone sees the session (isSeenSession): a headless run never is.
let envHostId = ''
// Whether someone sees this session (isSeenSession). Until then it takes no desktop id and, until it edits something,
// writes no presence (shouldPublish).
let seen = false
let toolLooks = 0
// A turn is running between prompt.submit and turn.complete: huddle messages are also copied into its next tool result.
let busy = false
let pending: string[] = []
// The peers as the last tick read them, for names and liveness between ticks.
let peersSeen: Presence[] = []
// directory -> its git top level ('' when it is not in a repo, remembered for a minute); top level -> repo identity.
const topCache = new Map<string, { top: string; at: number }>()
const identityCache = new Map<string, { repoKey: string; repoName: string }>()

/** Claude Code's `language` setting, then what the person writes, then LC_ALL/LANG; English by default. */
async function detectLang($: Api): Promise<Lang> {
  const settings = (await $.settings.read().catch(() => ({}))) as { language?: unknown }
  const locale = (await $.env.get('LC_ALL').catch(() => null)) || (await $.env.get('LANG').catch(() => null)) || null
  return pickLang(undefined, settings.language, locale, inferred)
}

/** `p`, or undefined when it fails or takes longer than `ms`. */
function withTimeout<T>($: Api, p: Promise<T>, ms: number): Promise<T | undefined> {
  return new Promise(resolve => {
    const t = $.clock.after(ms, () => resolve(undefined))
    p.then(
      v => {
        t.cancel()
        resolve(v)
      },
      () => {
        t.cancel()
        resolve(undefined)
      },
    )
  })
}

async function git($: Api, cwd: string, args: string[]) {
  const r = await $.process.run(['git', ...args], { cwd, timeoutMs: 5000 })
  return r.exitCode === 0 ? r.stdout.trim() : ''
}

/** `git -C <dir> ...`, '' on any failure (no such directory, not a repo, timeout). */
async function gitC($: Api, where: string, args: string[]) {
  const r = await $.process.run(['git', '-C', where, ...args], { timeoutMs: 5000 }).catch(() => null)
  return r && r.exitCode === 0 ? r.stdout.trim() : ''
}

async function save($: Api) {
  if (!me || !shouldPublish(seen, me)) return
  const now = await $.clock.now()
  me.lastSeen = now
  me.repos[me.home]!.seenAt = now
  // Only what still counts is kept: files edited in the last 4 hours, repos seen in the last 4 hours.
  for (const [key, repo] of Object.entries(me.repos)) {
    for (const [file, at] of Object.entries(repo.files)) if (now - at >= FILE_WINDOW_MS) delete repo.files[file]
    if (key !== me.home && now - (repo.seenAt ?? 0) >= FILE_WINDOW_MS) delete me.repos[key]
  }
  await $.fs.write(`${dir}/${me.sessionId}.json`, JSON.stringify(me))
}

async function readPeers($: Api, now: number): Promise<Presence[]> {
  const peers: Presence[] = []
  for (const entry of await $.fs.list(dir)) {
    if (entry.kind !== 'file' || !entry.name.endsWith('.json')) continue
    const path = `${dir}/${entry.name}`
    try {
      const text = await $.fs.read(path)
      if (!text) continue
      const p = upgradePresence(JSON.parse(text))
      if (!p) continue
      if (now - p.lastSeen > STALE_MS) {
        // No delete in $.fs: a session gone for a day is emptied, and an empty file is skipped.
        await $.fs.write(path, '').catch(() => null)
        continue
      }
      peers.push(p)
    } catch {
      // half-written by a peer this instant, or emptied when stale; the next tick reads it
    }
  }
  peersSeen = peers
  return peers
}

/** This session's sidebar title from the desktop app, when the app is there and lets it be read without asking. */
async function refreshTitle($: Api) {
  if (!me?.hostId) return
  const tools = await $.tool.list()
  if (!tools.some(t => t.name === GET_SESSION)) return
  const input = { tool: GET_SESSION, session_id: 'self' } as never
  const { decision } = await $.tool.check(input)
  if (decision !== 'allow') return
  const { text } = (await $.tool.call(input)) as { text?: string }
  const answer = text ? (JSON.parse(text) as { title?: unknown }) : undefined
  if (typeof answer?.title === 'string' && answer.title.trim()) me.title = answer.title.trim().slice(0, 120)
  // The session that started this one, while the person has not moved it to top level.
  if (answer) me.parentHostId = parentFromSession(answer)
}

/** Tells the mother, once, that two of her daughters edit the same files. Best effort; only when she is live. */
async function tellMother($: Api, peers: Presence[], sisters: Alert[], now: number) {
  const mother = me && motherOf(me, peers, now)
  if (!me || !mother || sisters.length === 0) return
  await $.session.send({ to: { sessionId: mother.sessionId }, text: sisterNotice(w, me, sisters) }).catch(() => null)
}

/** Opens a session of the desktop app by its own link, through the OS: the band may be drawn where links can't. */
async function openSession($: Api, hostId: string) {
  // `start` goes through cmd on Windows: only an id the app could have written reaches it.
  if (!isHostId(hostId)) return
  const url = sessionLink(hostId)
  const isWindows = (await $.env.get('OS')) === 'Windows_NT'
  const tries = isWindows ? [['cmd', '/c', 'start', '', url]] : [['open', url], ['xdg-open', url]]
  for (const argv of tries) {
    const r = await $.process.run(argv, { timeoutMs: 5000 }).catch(() => null)
    if (r?.exitCode === 0) return
  }
  $.ui.toast(w.openFailed)
}

// ---- Repos: which one a file or a directory belongs to ----

/** The git top level of a directory (or of the nearest parent that is a repo, for a folder a Write is about to
 * create); '' when it is in none. Remembered per directory. */
async function toplevelOf($: Api, start: string): Promise<string> {
  const now = await $.clock.now()
  let d = slashes(start)
  const tried: string[] = []
  for (let i = 0; i < 5 && d; i++) {
    const hit = topCache.get(d)
    let top = ''
    if (hit && (hit.top || now - hit.at < NEGATIVE_MS)) top = hit.top
    else {
      top = slashes(await gitC($, d, ['rev-parse', '--show-toplevel']))
      topCache.set(d, { top, at: now })
    }
    if (top) {
      for (const t of tried) topCache.set(t, { top, at: now })
      return top
    }
    tried.push(d)
    const parent = d.replace(/\/[^/]*$/, '')
    if (!parent || parent === d) break
    d = parent
  }
  return ''
}

/** A repo's key and name: its normalized origin, else its absolute git directory (as session.start does). */
async function identityOf($: Api, toplevel: string): Promise<{ repoKey: string; repoName: string }> {
  const cached = identityCache.get(toplevel)
  if (cached) return cached
  const remote = await gitC($, toplevel, ['config', '--get', 'remote.origin.url'])
  const commonDir = remote ? '' : await gitC($, toplevel, ['rev-parse', '--path-format=absolute', '--git-common-dir'])
  const repoKey = remote ? normalizeRemote(remote) : slashes(commonDir || toplevel)
  const id = { repoKey, repoName: repoNameOf(repoKey, toplevel) }
  if (identityCache.size > 200) identityCache.clear()
  identityCache.set(toplevel, id)
  return id
}

/** The session's entry for the repo at `toplevel`, made when it is the first time it is edited or entered. */
async function noteRepo($: Api, toplevel: string, now: number): Promise<RepoEntry | null> {
  if (!me || !toplevel) return null
  const byTop = Object.values(me.repos).find(r => r.toplevel === toplevel)
  const known = byTop ?? me.repos[(await identityOf($, toplevel)).repoKey]
  if (known) {
    known.seenAt = now
    return known
  }
  const id = await identityOf($, toplevel)
  const entry: RepoEntry = {
    ...id,
    toplevel,
    branch: await gitC($, toplevel, ['rev-parse', '--abbrev-ref', 'HEAD']),
    files: {},
    seenAt: now,
  }
  me.repos[id.repoKey] = entry
  return entry
}

// ---- Edits: through the file tools, and through the shell (what a command changed in the repos it works in) ----

type Hit = { repoKey: string; repoName: string; rel: string }
type Watched = { top: string; entry: RepoEntry; snap: Snapshot | null; startedAt: number }

/** One repo's dirty files and, for at most 300 of them, a signature of mtime and size. Null when git can't say. */
async function snapshot($: Api, top: string, prefer?: Snapshot | null): Promise<Snapshot | null> {
  const r = await $.process
    .run(['git', '-C', top, 'status', '--porcelain=v1', '-z', '--untracked-files=all'], { timeoutMs: SNAPSHOT_MS })
    .catch(() => null)
  if (!r || r.exitCode !== 0) return null
  const status = parsePorcelain(r.stdout)
  const snap: Snapshot = {}
  for (const [path, st] of Object.entries(status)) snap[path] = { status: st }
  // The files the first snapshot signed come first, so the two can be compared.
  const paths = Object.keys(snap).sort((a, b) => Number(prefer?.[b]?.sig !== undefined) - Number(prefer?.[a]?.sig !== undefined))
  await Promise.all(
    paths.slice(0, STAT_CAP).map(async path => {
      const st = await $.fs.stat(`${top}/${path}`).catch(() => null)
      if (st) snap[path]!.sig = `${st.mtimeMs}:${st.size}`
    }),
  )
  return snap
}

/** Before a shell command: the repos to watch (home, the directories it names, those visited in the last 4 h),
 * each with its dirty files. A command that enters a repo makes this session visit it. */
async function beforeBash($: Api, command: string): Promise<Watched[]> {
  if (!me) return []
  const now = await $.clock.now()
  const cwd = slashes(await $.session.cwd().catch(() => me!.cwd))
  const named = new Set<string>()
  for (const d of dirsInCommand(command, cwd, homeDir).slice(0, 6)) {
    const top = await toplevelOf($, d)
    if (top) named.add(top)
  }
  const tops = [me.repos[me.home]!.toplevel]
  for (const top of named) tops.push(top)
  const recent = Object.values(me.repos)
    .filter(r => r.repoKey !== me!.home && now - (r.seenAt ?? 0) < FILE_WINDOW_MS)
    .sort((a, b) => (b.seenAt ?? 0) - (a.seenAt ?? 0))
  for (const r of recent) tops.push(r.toplevel)

  const watched: Watched[] = []
  let entered = false
  for (const top of named) {
    const before = Object.keys(me.repos).length
    await noteRepo($, top, now)
    if (Object.keys(me.repos).length !== before) entered = true
  }
  for (const top of [...new Set(tops)].slice(0, SNAPSHOT_REPOS)) {
    const entry = Object.values(me.repos).find(r => r.toplevel === top) ?? (await noteRepo($, top, now))
    if (entry) watched.push({ top, entry, snap: null, startedAt: now })
  }
  await Promise.all(watched.map(async t => (t.snap = await snapshot($, t.top))))
  if (entered) save($).catch(() => {})
  return watched
}

/** After it: what changed in those repos is this session's edit. */
async function afterBash($: Api, watched: Watched[]): Promise<Hit[]> {
  const now = await $.clock.now()
  const hits: Hit[] = []
  if (!watched.some(t => t.snap)) return hits
  const peers = (await readPeers($, now).catch(() => peersSeen)).filter(p => p.sessionId !== me?.sessionId && isLive(p, now))
  await Promise.all(
    watched.map(async t => {
      if (!t.snap) return
      const after = await snapshot($, t.top, t.snap)
      if (!after) return
      for (const rel of diffSnapshots(t.snap, after)) {
        // In a shared working copy another session may have written meanwhile: what it recorded is not ours.
        if (peers.some(p => (p.repos[t.entry.repoKey]?.files[rel] ?? 0) >= t.startedAt)) continue
        t.entry.files[rel] = now
        t.entry.seenAt = now
        hits.push({ repoKey: t.entry.repoKey, repoName: t.entry.repoName, rel })
      }
    }),
  )
  return hits
}

/** A write through Edit/Write/MultiEdit/NotebookEdit: the file's own repo, wherever it is. */
async function afterEdit($: Api, input: { file_path?: string; notebook_path?: string }): Promise<Hit[]> {
  if (!me) return []
  const given = input.file_path ?? input.notebook_path
  if (!given) return []
  const path = resolvePath(slashes(await $.session.cwd().catch(() => me!.cwd)), given)
  const top = await toplevelOf($, path.replace(/\/[^/]*$/, '') || '/')
  const now = await $.clock.now()
  const entry = await noteRepo($, top, now)
  if (!entry) return []
  let rel = repoRelative(top, path)
  if (!rel) {
    // git spells the top level with symbolic links resolved; the tool may not have.
    const real = (await $.fs.stat(path, { resolve: true }).catch(() => null))?.realPath
    rel = real ? repoRelative(top, real) : null
  }
  if (!rel) return []
  entry.files[rel] = now
  return [{ repoKey: entry.repoKey, repoName: entry.repoName, rel }]
}

// ---- Huddle ----

/** The leader's lead as it is now on disk (a member reads it fresh: the agreement may be seconds old). */
async function currentLead($: Api) {
  if (!me?.huddle) return undefined
  if (me.huddle.leaderId === me.sessionId) return me.huddle.lead
  try {
    return upgradePresence(JSON.parse(await $.fs.read(`${dir}/${me.huddle.leaderId}.json`)))?.huddle?.lead
  } catch {
    return leaderOf(me, peersSeen)?.huddle?.lead
  }
}

/** Notes for edits that fall on a file the agreement gave to another live member; a toast the first time per file. */
async function ownerNotes($: Api, hits: Hit[]): Promise<string[]> {
  if (!me || hits.length === 0 || !me.huddle) return []
  const lead = await currentLead($)
  if (!lead) return []
  const now = await $.clock.now()
  const notes: string[] = []
  for (const hit of hits) {
    const ownerId = ownerOf(lead, hit.repoKey, hit.rel)
    if (!ownerId || ownerId === me.sessionId) continue
    const owner = peersSeen.find(p => p.sessionId === ownerId)
    if (!owner || !isLive(owner, now)) continue
    const name = nameOf(w, owner)
    notes.push(w.ownerConflict(hit.rel, name))
    const key = ownerKey(hit.repoKey, hit.rel)
    if (!warned.has(key)) {
      warned.add(key)
      $.ui.toast(w.toastOwner(hit.rel, name))
    }
  }
  return notes
}

/** A member's first message to anyone after joining confirms the huddle. */
async function markAck($: Api) {
  const h = me?.huddle
  if (!me || !h || h.leaderId === me.sessionId || h.ackAt) return
  h.ackAt = await $.clock.now()
  await save($)
}

async function onReceive($: Api, e: { text: string }) {
  if (!me) return
  const now = await $.clock.now()
  const add = parseAddMarker(e.text)
  const lead = me.huddle?.leaderId === me.sessionId ? me.huddle.lead : undefined
  if (add && lead && me.huddle?.id === add.id) {
    lead.members = [...new Set([...lead.members, ...add.sessionIds.filter(id => id !== me!.sessionId)])]
    await save($)
  }
  const marker = parseHuddleMarker(e.text)
  if (marker && marker.leaderId !== me.sessionId) {
    // A leader keeps its own huddle; anyone else follows the latest one that reached it.
    const mine = me.huddle
    if (!mine || (mine.id !== marker.id && mine.leaderId !== me.sessionId)) {
      me.huddle = { id: marker.id, leaderId: marker.leaderId, joinedAt: now }
      await save($)
    }
  }
  if (busy && (marker || add)) {
    const leader = marker && peersSeen.find(p => p.sessionId === marker.leaderId)
    const from = leader ? nameOf(w, leader) : w.aMember
    pending = [...pending, w.midTurnNote(from, compactForMidTurn(e.text))].slice(-PENDING_MAX)
  }
}

async function onPrompt($: Api, e: { text: string; origin: { kind: string } }) {
  busy = true
  if (!me || !HUMAN_ORIGINS.has(e.origin.kind)) return
  me.lastActiveAt = await $.clock.now()
  const task = taskFromPrompt(e.text)
  if (task && !me.task) {
    me.task = task
    // The first thing the person types says which language they work in.
    inferred = inferLang(e.text.slice(0, 2000)) ?? inferred
    const lang = await detectLang($)
    w = words(lang)
    me.lang = lang
  }
  save($).catch(() => {})
}

/** What a tool call adds after it ran: ownership notes for what it edited, and huddle messages that arrived mid-turn. */
async function afterTool(
  $: Api,
  e: { tool: string; agentId?: string; file_path?: string; notebook_path?: string },
  ran: ToolCallResult,
  watched: Watched[],
): Promise<ToolCallResult> {
  if (ran.deny !== undefined) return ran
  const notes: string[] = []
  let hits: Hit[] = []
  if (e.tool === 'Bash') hits = await afterBash($, watched)
  else if (EDIT_TOOLS.has(e.tool) && !ran.isError) hits = await afterEdit($, e)
  if (hits.length) {
    notes.push(...(await ownerNotes($, hits)))
    save($).catch(() => {})
    refresh($).catch(() => {})
  }
  if (!e.agentId && pending.length) {
    notes.push(...pending)
    pending = []
  }
  return notes.length ? { ...ran, context: [...(ran.context ?? []), ...notes] } : ran
}

/** One look at the peers. `timer` marks the clock's own tick: only those count toward re-reading the title. */
async function refresh($: Api, timer = false) {
  if (!me) return
  if (!seen) {
    const surfaces = await $.session.surfaces().catch(() => [])
    // The desktop's tools are there from the start (or within its first minutes): a run without them by then is headless,
    // and only a surface can still make it seen. That spares a long SDK run a tool list every tick.
    const look = surfaces.length === 0 && toolLooks < TOOL_LOOKS_MAX
    if (look) toolLooks++
    const tools = look ? ((await withTimeout($, $.tool.list(), LIST_TIMEOUT_MS)) ?? []).map(t => t.name) : []
    seen = isSeenSession(seen, surfaces, tools)
  }
  if (!me.hostId && seen && isHostId(envHostId)) me.hostId = envHostId
  if (timer && shouldRefreshTitle(ticks++)) await refreshTitle($).catch(() => {})
  const now = await $.clock.now()
  await Promise.all(
    activeRepos(me, now)
      .slice(0, 5)
      .map(async r => (r.branch = (await gitC($, r.toplevel, ['rev-parse', '--abbrev-ref', 'HEAD'])) || r.branch)),
  )
  await save($)
  const peers = await readPeers($, now)
  // A huddle nobody in it keeps alive is over (unless this session only just joined and the leader's file is not in yet).
  if (me.huddle && now - me.huddle.joinedAt > 2 * 60_000 && !liveHuddle(me, peers, now)) me.huddle = undefined

  const all = assessAll(me, peers, now)
  const state = bandState(me, peers, now)
  if (!sameJson(await read($, alerts), all)) await update($, alerts, () => all)
  if (!sameJson(await read($, band), state)) await update($, band, () => state)

  if (state.kind === 'alert') {
    const snoozed = (await read($, snoozeUntil)) > now
    for (const a of state.alerts) {
      const key = `${a.sessionId}:${a.repoKey}:${a.level}`
      if (a.level < 3 || toasted.has(key) || snoozed) continue
      toasted.add(key)
      $.ui.toast(w.toastClash(a.repoName, reasonOf(w, a)))
      if (a.family === 'sister') void tellMother($, peers, [a], now)
    }
    $.ui.status(w.status(state.alerts.length + 1, state.alerts[0]!.repoName))
  } else {
    $.ui.status(state.kind === 'huddle' ? w.statusHuddle(state.size) : undefined)
  }
}

/** Starts a huddle with every live peer in the shared repos, or adds those who are not yet in the one that is live.
 * Answers what the toast says. */
async function coordinate($: Api): Promise<string> {
  if (!me) return w.commandNotRepo
  // Titles are what the person sees in the messages: take this session's and the peers' as they are now.
  await refreshTitle($).catch(() => {})
  const now = await $.clock.now()
  const peers = await readPeers($, now)
  const current = assessAll(me, peers, now)
  const members = huddleMembers(me, peers, now)
  const targets = current.filter(a => !members?.has(a.sessionId))
  if (targets.length === 0) {
    const told = current.length ? w.toastAllIn : w.toastNoPeers
    $.ui.toast(told)
    return told
  }
  if (!members) {
    me.huddle = {
      id: newHuddleId(me.sessionId, now),
      leaderId: me.sessionId,
      joinedAt: now,
      lead: { members: [], owners: {}, createdAt: now },
    }
  }
  const h = me.huddle!
  const isLeader = h.leaderId === me.sessionId
  if (isLeader && !h.lead) h.lead = { members: [], owners: {}, createdAt: now }

  const sent: string[] = []
  const failed: string[] = []
  for (const a of targets) {
    const r = await $.session
      .send({ to: { sessionId: a.sessionId }, text: peerMessage(w, me, a, now, { id: h.id, leaderId: h.leaderId }) })
      .catch(err => ({ isDelivered: false as const, reason: String(err) }))
    if (r.isDelivered) sent.push(a.sessionId)
    else failed.push(`${a.sessionId.slice(0, 8)}: ${r.reason}`)
  }
  // Sisters clash on the same files: their mother hears of it once, and the alert loop doesn't repeat it.
  const sisters = targets.filter(a => a.family === 'sister')
  if (sisters.length) {
    for (const a of sisters) toasted.add(`${a.sessionId}:${a.repoKey}:${a.level}`)
    await tellMother($, peers, sisters, now)
  }
  const names = targets.filter(a => sent.includes(a.sessionId)).map(a => nameOf(w, a)).join(', ')
  if (sent.length) {
    if (isLeader) h.lead!.members = [...new Set([...h.lead!.members, ...sent])]
    // A member that adds tells the leader, who keeps the list and takes the replies.
    else void $.session.send({ to: { sessionId: h.leaderId }, text: w.addedNotice(names, addMarker(h.id, sent)) }).catch(() => null)
  }
  await save($)
  await update($, lastCoord, () => ({ at: now, sent: sent.length, failed }))
  const told = failed.length ? w.toastPartial(sent.length, failed.length) : members ? w.toastAdded(sent.length) : w.toastSent(sent.length)
  $.ui.toast(told)
  if (!members) void $.prompt.submit({ text: leadPrompt(w, me, targets, sent) })
  else if (isLeader && sent.length) void $.prompt.submit({ text: w.leadAdded(names) })
  refresh($).catch(() => {})
  return told
}

type AgreeInput = { summary?: unknown; owners?: unknown }

/** The `agree` tool: the leader records who owns which file and tells every member. */
async function agree($: Api, input: AgreeInput): Promise<{ result: string } | { deny: string }> {
  const h = me?.huddle
  if (!me || !h) return { deny: w.agreeNoHuddle }
  if (h.leaderId !== me.sessionId || !h.lead) return { deny: w.agreeNotLeader }
  const summary = typeof input.summary === 'string' ? input.summary.trim() : ''
  const given = Array.isArray(input.owners) ? (input.owners as { repo?: unknown; path?: unknown; sessionId?: unknown }[]) : []
  if (!summary || given.length === 0) return { deny: w.agreeBadInput }

  const now = await $.clock.now()
  const peers = await readPeers($, now)
  const everyone = [me, ...peers]
  const repos = everyone.flatMap(p => Object.values(p.repos))
  const owners: Record<string, string> = {}
  const lines: string[] = []
  for (const o of given) {
    const sessionId = typeof o.sessionId === 'string' ? o.sessionId : ''
    let path = typeof o.path === 'string' ? slashes(o.path).replace(/^\.\//, '') : ''
    if (!ID_RE.test(sessionId) || !path) return { deny: w.agreeBadInput }
    const asked = typeof o.repo === 'string' ? o.repo.trim() : ''
    let repo = asked
      ? repos.find(r => r.repoKey === asked) ?? repos.find(r => r.repoName.toLowerCase() === asked.toLowerCase())
      : me.repos[me.home]
    if (!repo) return { deny: w.agreeBadRepo(asked) }
    if (!asked) {
      // An absolute path names its own repo.
      const inside = repos.find(r => repoRelative(r.toplevel, path) !== null)
      if (inside && path.startsWith('/')) repo = inside
    }
    path = repoRelative(repo.toplevel, path) ?? path
    owners[ownerKey(repo.repoKey, path)] = sessionId
    const owner = everyone.find(p => p.sessionId === sessionId)
    lines.push(`- ${repo.repoName}/${path} → ${owner ? nameOf(w, owner) : sessionId.slice(0, 8)} (${sessionId})`)
  }

  h.lead.owners = owners
  h.lead.summary = summary
  h.lead.agreedAt = now
  const text = w.agreeMessage({ summary, owners: lines, marker: huddleMarker(h.id, me.sessionId) })
  const memberIds = new Set([...h.lead.members, ...peers.filter(p => p.huddle?.id === h.id).map(p => p.sessionId)])
  memberIds.delete(me.sessionId)
  let sent = 0
  let failed = 0
  for (const id of memberIds) {
    if (!peers.some(p => p.sessionId === id && isLive(p, now))) continue
    const r = await $.session.send({ to: { sessionId: id }, text }).catch(() => ({ isDelivered: false as const }))
    if (r.isDelivered) sent++
    else failed++
  }
  await save($)
  refresh($).catch(() => {})
  return { result: w.agreeDone(sent, failed) }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    const cwd = await $.session.cwd()
    const toplevel = await git($, cwd, ['rev-parse', '--show-toplevel'])
    if (!toplevel) {
      w = words(await detectLang($))
      return started
    }

    const commonDir = await git($, cwd, ['rev-parse', '--path-format=absolute', '--git-common-dir'])
    const remote = await git($, cwd, ['config', '--get', 'remote.origin.url'])
    const repoKey = remote ? normalizeRemote(remote) : slashes(commonDir)
    const now = await $.clock.now()
    homeDir = slashes((await $.env.get('HOME')) || (await $.env.get('USERPROFILE')) || '')
    dir = `${homeDir}/.claude/huddle/sessions`

    const home: RepoEntry = {
      repoKey,
      repoName: repoNameOf(repoKey, slashes(toplevel)),
      toplevel: slashes(toplevel),
      branch: await git($, cwd, ['rev-parse', '--abbrev-ref', 'HEAD']),
      files: {},
      seenAt: now,
    }
    me = {
      v: 2,
      sessionId: await $.session.id(),
      cwd,
      home: repoKey,
      repos: { [repoKey]: home },
      task: '',
      hostId: undefined,
      startedAt: now,
      lastSeen: now,
      lastActiveAt: now,
    }
    // A reload keeps the session: pick up what this session already recorded.
    try {
      const saved = upgradePresence(JSON.parse(await $.fs.read(`${dir}/${me.sessionId}.json`)))
      if (saved) {
        me.task = saved.task
        me.title = saved.title
        me.parentHostId = saved.parentHostId
        me.huddle = saved.huddle
        me.startedAt = saved.startedAt
        me.lastActiveAt = saved.lastActiveAt
        me.repos = { ...saved.repos, [repoKey]: { ...home, files: saved.repos[repoKey]?.files ?? {} } }
        if (saved.task) inferred = inferLang(saved.task)
      }
    } catch {
      // first start
    }
    // Read here too: after a reload the task is already known and the first prompt never comes again.
    envHostId = (await $.env.get('CLAUDE_CODE_HOST_SESSION_ID').catch(() => undefined)) || ''
    const lang = await detectLang($)
    w = words(lang)
    me.lang = lang

    await $.command.register({ name: 'huddle', description: w.commandDescription })
    await $.tool.register({ name: 'peers', description: w.toolPeers })
    await $.tool.register({
      name: 'send',
      description: w.toolSend,
      inputSchema: {
        type: 'object',
        properties: { sessionId: { type: 'string' }, text: { type: 'string' } },
        required: ['sessionId', 'text'],
      },
    })
    await $.tool.register({
      name: 'agree',
      description: w.toolAgree,
      inputSchema: {
        type: 'object',
        properties: {
          summary: { type: 'string' },
          owners: {
            type: 'array',
            items: {
              type: 'object',
              properties: { repo: { type: 'string' }, path: { type: 'string' }, sessionId: { type: 'string' } },
              required: ['path', 'sessionId'],
            },
          },
        },
        required: ['summary', 'owners'],
      },
    })

    await refresh($, true)
    $.clock.every(TICK_MS, () => void refresh($, true).catch(() => {}))
    return started
  })

  on('command.run', { command: 'huddle' }, async $ => ({ text: await coordinate($) }))

  on('prompt.submit', async ($, e, next) => {
    // The task is what a person asked: typed, sent from a phone or an SDK host; never a peer's or a plugin's text.
    await onPrompt($, e).catch(() => {})
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) busy = false
    return next(e)
  })

  // Outside the desktop app the title comes with the prompt (a /rename in the terminal, say).
  on('classic.UserPromptSubmit', async ($, e, next) => {
    if (me && e.session_title && e.session_title !== me.title) {
      me.title = e.session_title.slice(0, 120)
      save($).catch(() => {})
    }
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    // A shell command is looked at before and after: what changed in between is this session's edit.
    let watched: Watched[] = []
    try {
      if (me) {
        me.lastActiveAt = await $.clock.now()
        if (e.tool === 'Bash') watched = await beforeBash($, e.command)
      }
    } catch {
      // watching is best effort; the command still runs
    }
    const ran = await next(e)
    if (!me) return ran
    // Recording never changes the tool's result: the edit already happened.
    return afterTool($, e as never, ran, watched).catch(() => ran)
  })

  // The engine's tool names don't list a mod's own tools: the exact name is cast, so matching stays a plain string match.
  on('tool.call', { tool: 'mcp__huddle__peers' as never }, async $ => {
    try {
      const list = await read($, alerts)
      return { result: list.length ? JSON.stringify(list, null, 2) : w.peersNone }
    } catch (err) {
      return { deny: `huddle: ${String(err)}` }
    }
  })

  on('tool.call', { tool: 'mcp__huddle__send' as never }, async ($, e) => {
    const { sessionId, text } = e as unknown as { sessionId: string; text: string }
    try {
      const r = await $.session.send({ to: { sessionId }, text })
      if (r.isDelivered) await markAck($).catch(() => {})
      return r.isDelivered ? { result: w.delivered } : { deny: w.notDelivered(r.reason) }
    } catch (err) {
      return { deny: w.notDelivered(String(err)) }
    }
  })

  on('tool.call', { tool: 'mcp__huddle__agree' as never }, async ($, e) => {
    try {
      return await agree($, e as unknown as AgreeInput)
    } catch (err) {
      return { deny: `huddle: ${String(err)}` }
    }
  })

  // Joining a huddle is a matter of reading its marker; the message itself is always delivered.
  on('session.receive', async ($, e, next) => {
    await onReceive($, e).catch(() => {})
    return next(e)
  })

  on('session.send', async ($, e, next) => {
    const r = await next(e)
    if (r.isDelivered) await markAck($).catch(() => {})
    return r
  })

  on('session.end', async ($, e, next) => {
    if (me) {
      me.ended = true
      await save($).catch(() => {})
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const state = await read($, band)
    const now = await $.clock.now()
    if (!me || e.props.hasSurvey || state.kind === 'none') return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)

    // The dim family line closes every band: who started this session, how many it started.
    const fam: Family | undefined = state.family
    const mother = fam?.mother
    const familyRow = fam && (
      <Box flexDirection="row" gap={1}>
        {mother?.hostId ? (
          <Button key="open-mother" plain onPress={() => openSession($, mother.hostId)}>
            <Text dimColor underline>
              ◦ {w.familyBy} {nameOf(w, mother)}
            </Text>
          </Button>
        ) : (
          <Text dimColor>◦ {mother ? w.familyMother(nameOf(w, mother)) : ''}</Text>
        )}
        {fam.daughters > 0 && <Text dimColor>{mother ? '· ' : ''}{w.familyDaughters(fam.daughters)}</Text>}
      </Box>
    )

    if (state.kind === 'family') {
      return (
        <Box flexDirection="column" marginTop={1}>
          {familyRow}
        </Box>
      )
    }

    if (state.kind === 'huddle') {
      const led = state.leader
      return (
        <Box flexDirection="column" marginTop={1}>
          <Box flexDirection="row" gap={1}>
            <Text color="success">
              ✓ {w.huddleWith(state.size)} · {state.leaderIsMe ? w.ledByYou : w.ledBy}
            </Text>
            {!state.leaderIsMe &&
              (led.hostId ? (
                <Button key="open-leader" plain onPress={() => openSession($, led.hostId)}>
                  <Text color="success" underline>
                    {nameOf(w, led)}
                  </Text>
                </Button>
              ) : (
                <Text color="success">{nameOf(w, led)}</Text>
              ))}
            <Text dimColor>· {w.confirmed(state.confirmed, state.size)}</Text>
          </Box>
          {state.conflicts.slice(0, 2).map(c => (
            <Text color="warning" dimColor>
              ▲ {w.editedOwned(nameOf(w, c.editor), c.file, nameOf(w, c.owner))}
            </Text>
          ))}
          {familyRow}
        </Box>
      )
    }

    if ((await read($, snoozeUntil)) > now) return next(e)
    const list = state.alerts
    const top = list[0]!.level
    const done = await read($, lastCoord)

    return (
      <Box flexDirection="column" marginTop={1}>
        {list.slice(0, 3).map(a => (
          <Box flexDirection="row" gap={1}>
            <Text color={LEVEL_COLOR[a.level]}>
              {LEVEL_MARK[a.level]} {a.level === 3 ? w.clash : w.otherAgent} {w.in} {a.repoName} · {reasonOf(w, a)}
              {a.overlap.length ? ` (${a.overlap.slice(0, 3).join(', ')}${a.overlap.length > 3 ? '…' : ''})` : ''} ·
            </Text>
            {a.hostId ? (
              <Button key={`open-${a.sessionId}`} plain onPress={() => openSession($, a.hostId)}>
                <Text color={LEVEL_COLOR[a.level]} underline>
                  {nameOf(w, { title: a.title, task: a.task.slice(0, 60) })}
                </Text>
              </Button>
            ) : (
              <Text color={LEVEL_COLOR[a.level]}>{nameOf(w, { title: a.title, task: a.task.slice(0, 60) })}</Text>
            )}
            <Text dimColor>· {a.branch}</Text>
          </Box>
        ))}
        {list.length > 3 && <Text dimColor>  {w.more(list.length - 3)}</Text>}
        <Box flexDirection="row" gap={1}>
          {top === 3 && <Text color="error" bold>{w.recommend}</Text>}
          <Button key="coord" variant={top === 3 ? 'primary' : undefined} onPress={() => coordinate($)}>
            {state.hasHuddle ? w.addToHuddle : w.coordinate}
          </Button>
          <Button key="snooze" onPress={() => update($, snoozeUntil, () => now + SNOOZE_MS)}>
            {w.snooze}
          </Button>
          {done && now - done.at < 10 * 60_000 && (
            <Text dimColor>
              {w.sentTo(done.sent)}
              {done.failed.length ? w.failedN(done.failed.length) : ''}
            </Text>
          )}
        </Box>
        {familyRow}
      </Box>
    )
  })
}

files.hooks/logic.ts:
import type { Alert, AlertKind, BandState, Family, Level, OwnerConflict, Who } from '../types'
import type { Lang, Words } from './i18n'

/** What a session knows of one repo it works in: its working copy there, its branch, the files it edited. */
export type RepoEntry = {
  repoKey: string
  repoName: string
  toplevel: string
  branch: string
  files: Record<string, number>
  /** When the session last edited or entered this repo. A repo not seen for the file window stops counting. */
  seenAt?: number
}

/** What the leader decided: who owns which disputed file. `owners` keys are `repoKey::relPath`. */
export type HuddleLead = {
  members: string[]
  owners: Record<string, string>
  summary?: string
  createdAt: number
  /** When `agree` last recorded the owners: only edits after it can break the agreement. */
  agreedAt?: number
}

export type HuddleInfo = {
  id: string
  leaderId: string
  joinedAt: number
  ackAt?: number
  lead?: HuddleLead
}

// One file per live session under ~/.claude/huddle/sessions/<sessionId>.json.
export type Presence = {
  v: 2
  sessionId: string
  cwd: string
  /** The repo of the session's working directory; always in `repos`. */
  home: string
  repos: Record<string, RepoEntry>
  task: string
  title?: string
  hostId?: string
  /** The desktop id of the session that started this one (start_session), while it is not detached. */
  parentHostId?: string
  lang?: Lang
  huddle?: HuddleInfo
  startedAt: number
  lastSeen: number
  /** Last human prompt or tool call: a session open but untouched for hours is idle. */
  lastActiveAt: number
  ended?: boolean
}

export const LIVE_MS = 60_000
export const FILE_WINDOW_MS = 4 * 60 * 60_000
export const IDLE_MS = 2 * 60 * 60_000

// Files only one session should touch at a time (single-owner).
const HOT = [
  /(^|\/)package\.json$/,
  /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock|bun\.lockb?)$/,
  /(^|\/)migrations?\//,
  /(^|\/)(schema\.prisma|drizzle\.config\.\w+)$/,
  /(^|\/)(schema|db\/schema)\.\w+$/,
  /(^|\/)generated\//,
]

export const isHot = (path: string) => HOT.some(re => re.test(path))

// git remote spellings collapse to one key: git@github.com:o/r.git == https://github.com/o/r
export function normalizeRemote(url: string): string {
  return url
    .trim()
    .replace(/^[a-z+]+:\/\//, '')
    .replace(/^[^@/]+@/, '')
    .replace(':', '/')
    .replace(/\/+$/, '')
    .replace(/\.git$/, '')
    .toLowerCase()
}

const recent = (files: Record<string, number>, now: number) =>
  Object.keys(files).filter(f => now - (files[f] ?? 0) < FILE_WINDOW_MS)

export function isLive(p: Presence, now: number): boolean {
  return !p.ended && now - p.lastSeen < LIVE_MS
}

export const isIdle = (p: Presence, now: number): boolean => now - p.lastActiveAt > IDLE_MS

/**
 * A presence file as this version reads it. A session still on 0.2.x writes `v: 1` (one repo, flat); it is read as
 * a session whose only repo is its home. Anything else is skipped.
 */
export function upgradePresence(raw: unknown): Presence | null {
  const p = raw as Record<string, any> | null
  if (!p || typeof p !== 'object' || typeof p.sessionId !== 'string') return null
  if (p.v === 2) {
    if (!p.repos || typeof p.repos !== 'object' || typeof p.home !== 'string') return null
    return { ...p, lastActiveAt: typeof p.lastActiveAt === 'number' ? p.lastActiveAt : p.lastSeen } as Presence
  }
  if (p.v !== 1 || typeof p.repoKey !== 'string') return null
  const { files, toplevel, repoName, branch, repoKey, ...rest } = p
  return {
    ...rest,
    v: 2,
    home: repoKey,
    repos: { [repoKey]: { repoKey, repoName, toplevel, branch, files: files ?? {}, seenAt: p.lastSeen } },
    lastActiveAt: p.lastSeen,
  } as Presence
}

/** The repos that count right now: the home one always, the others while they were seen within the file window. */
export function activeRepos(p: Presence, now: number): RepoEntry[] {
  return Object.values(p.repos).filter(r => r.repoKey === p.home || now - (r.seenAt ?? p.lastSeen) < FILE_WINDOW_MS)
}

function assessRepo(mine: RepoEntry, theirs: RepoEntry, now: number): Pick<Alert, 'level' | 'kind' | 'overlap'> {
  const theirFiles = new Set(recent(theirs.files, now))
  const mineFiles = recent(mine.files, now)
  const overlap = mineFiles.filter(f => theirFiles.has(f)).sort()
  const bothHot = mineFiles.some(isHot) && [...theirFiles].some(isHot)
  const sameCheckout = mine.toplevel === theirs.toplevel
  const [level, kind]: [Level, AlertKind] =
    overlap.length > 0 ? [3, 'overlap'] : bothHot ? [3, 'hot'] : sameCheckout ? [2, 'checkout'] : [1, 'repo']
  return { level, kind, overlap }
}

/**
 * How two sessions clash. Every repo they both work in is judged on its own (same files 3, both on single-owner
 * files 3, same working copy 2, else 1) and the peer raises one alert, for its strongest repo.
 */
export function assess(me: Presence, peer: Presence, now: number): Alert | null {
  if (peer.sessionId === me.sessionId || !isLive(peer, now)) return null
  // A session and the one that started it (or one it started) already coordinate through the app.
  const family = familyOf(me, peer)
  if (family === 'mother' || family === 'daughter') return null

  const theirs = new Map(activeRepos(peer, now).map(r => [r.repoKey, r]))
  let best: { repo: RepoEntry; found: Pick<Alert, 'level' | 'kind' | 'overlap'> } | null = null
  for (const repo of activeRepos(me, now)) {
    const other = theirs.get(repo.repoKey)
    if (!other) continue
    const found = assessRepo(repo, other, now)
    const wins =
      !best ||
      found.level > best.found.level ||
      (found.level === best.found.level && found.overlap.length > best.found.overlap.length) ||
      (found.level === best.found.level && found.overlap.length === best.found.overlap.length && repo.repoKey === me.home)
    if (wins) best = { repo, found }
  }
  if (!best) return null
  // A session nobody has touched for hours only speaks up when the files already clash.
  if (isIdle(peer, now) && best.found.level < 3) return null
  // Sisters only speak up when their files clash.
  if (family === 'sister' && best.found.level < 3) return null

  const peerRepo = theirs.get(best.repo.repoKey)!
  return {
    sessionId: peer.sessionId,
    ...best.found,
    repoKey: best.repo.repoKey,
    repoName: best.repo.repoName,
    title: peer.title ?? '',
    hostId: isHostId(peer.hostId) ? peer.hostId : '',
    task: peer.task,
    branch: peerRepo.branch,
    ...(family === 'sister' ? { family } : {}),
  }
}

/** The session that started the one whose get_session answer this is; none once the person detached it. */
export function parentFromSession(answer: unknown): string | undefined {
  const a = answer as { parentSessionId?: unknown; detached?: unknown } | null
  if (!a || typeof a !== 'object' || a.detached === true) return undefined
  return isHostId(a.parentSessionId) ? a.parentSessionId : undefined
}

/** What `peer` is to `me` among sessions started from one another, by the desktop ids; null when unrelated or unknown. */
export function familyOf(me: Presence, peer: Presence): 'mother' | 'daughter' | 'sister' | null {
  if (me.parentHostId && me.parentHostId === peer.hostId) return 'mother'
  if (peer.parentHostId && peer.parentHostId === me.hostId) return 'daughter'
  if (me.parentHostId && me.parentHostId === peer.parentHostId) return 'sister'
  return null
}

/** The live session that started this one. */
export const motherOf = (me: Presence, peers: Presence[], now: number): Presence | undefined =>
  peers.find(p => p.sessionId !== me.sessionId && isLive(p, now) && familyOf(me, p) === 'mother')

export function assessAll(me: Presence, peers: Presence[], now: number): Alert[] {
  return peers
    .map(p => assess(me, p, now))
    .filter((a): a is Alert => a !== null)
    .sort((a, b) => b.level - a.level)
}

// Paths as git spells them: forward slashes, so Windows tool paths compare with `git rev-parse` output.
export const slashes = (path: string) => path.replace(/\\/g, '/')

/** The file relative to the repo's top level, or null when it lies outside it. */
export function repoRelative(toplevel: string, path: string): string | null {
  const root = slashes(toplevel).replace(/\/+$/, '') + '/'
  const file = slashes(path)
  return file.startsWith(root) ? file.slice(root.length) : null
}

export const reasonOf = (w: Words, a: Alert) =>
  w.reason(a.kind, a.overlap.length) + (a.family === 'sister' ? w.sisterSuffix : '')

const list = (w: Words, xs: string[], max = 8) =>
  xs.length === 0 ? w.none : xs.slice(0, max).join(', ') + (xs.length > max ? ` (+${xs.length - max})` : '')

const quote = (w: Words, s: string) => (s ? `«${s}»` : w.noTask)

/** How a session is named to the person: its sidebar title, else the start of what it was asked. */
export const nameOf = (w: Words, p: { title?: string; task: string }) => (p.title ? `«${p.title}»` : quote(w, p.task))

/** A desktop session id as the app spells it; anything else (from a peer's file) is never opened. */
export const isHostId = (id: unknown): id is string => typeof id === 'string' && /^[A-Za-z0-9_-]{1,80}$/.test(id)

/** The prefix of the tools the Claude desktop app gives the sessions it hosts (`mcp__ccd_session__...`, `mcp__ccd_turn__...`). */
export const DESKTOP_TOOL_PREFIX = 'mcp__ccd_'

/**
 * Whether this process is a session someone sees, and so may take the desktop app's id from CLAUDE_CODE_HOST_SESSION_ID
 * as its own: it draws on a surface (terminal, phone, IDE, desktop) or the desktop app hosts it (its `mcp__ccd_*` tools
 * are there even while the session is not open in the window, when `surfaces()` is empty for hours). A `claude -p` run
 * started from a desktop session inherits the variable but neither of these, so it never passes for its parent. Once
 * true it stays true. If a desktop release ever hands its `ccd` servers to child processes, this needs another signal.
 */
export function isSeenSession(before: boolean, surfaces: readonly unknown[], toolNames: readonly string[]): boolean {
  return before || surfaces.length > 0 || toolNames.some(n => n.startsWith(DESKTOP_TOOL_PREFIX))
}

/**
 * Whether this session writes its presence file for the others to read. One someone sees always does. A run no one sees
 * (a `claude -p` helper that a status line, a mod or a script starts) only once it has edited something in a repo: until
 * then it is no risk to anyone, and showing it would put a nameless peer in every band of that repo.
 */
export function shouldPublish(seen: boolean, me: Pick<Presence, 'repos'>): boolean {
  return seen || Object.values(me.repos).some(r => Object.keys(r.files).length > 0)
}

/** The desktop app's own link to a session, as its get_session answers it. */
export const sessionLink = (hostId: string) => `claude://claude.ai/epitaxy/${hostId}`

/** The repo entry a message speaks about: the alert's repo, else the session's home. */
const entryFor = (p: Presence, repoKey: string): RepoEntry => p.repos[repoKey] ?? p.repos[p.home]!

// What each peer session receives. `huddle` is the huddle it joins: with none, this session leads a new one.
export function peerMessage(
  w: Words,
  me: Presence,
  alert: Alert,
  now: number,
  huddle?: { id: string; leaderId: string },
): string {
  const repo = entryFor(me, alert.repoKey)
  return w.peerMessage({
    repo: alert.repoName,
    level: alert.level,
    reason: reasonOf(w, alert),
    id: me.sessionId,
    task: nameOf(w, me),
    branch: repo.branch,
    path: repo.toplevel,
    files: list(w, recent(repo.files, now)),
    clash: alert.overlap.length ? list(w, alert.overlap) : null,
    leader: huddle?.leaderId ?? me.sessionId,
    marker: huddle ? huddleMarker(huddle.id, huddle.leaderId) : '',
  })
}

/** The one short notice a mother gets when two of her daughters edit the same files. */
export function sisterNotice(w: Words, me: Presence, sisters: Alert[]): string {
  const files = [...new Set(sisters.flatMap(a => a.overlap))].sort()
  return w.sisterClashToMother(
    nameOf(w, me),
    sisters.map(a => nameOf(w, a)).join(', '),
    files.length ? list(w, files) : w.none,
  )
}

// What the initiating session's own model is asked to do.
export function leadPrompt(w: Words, me: Presence, alerts: Alert[], sent: string[]): string {
  const repos = [...new Set(alerts.map(a => a.repoName))].join(', ')
  return [
    w.leadIntro(repos),
    ...alerts.map(a =>
      w.leadRow({
        id: a.sessionId,
        level: a.level,
        reason: reasonOf(w, a),
        task: nameOf(w, a),
        branch: a.branch,
        clash: a.overlap.length ? list(w, a.overlap) : null,
        failed: !sent.includes(a.sessionId),
      }),
    ),
    w.leadClose,
  ].join('\n')
}

export function sameJson(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b)
}

export const sameAlerts = (a: Alert[], b: Alert[]): boolean => sameJson(a, b)

// ---- Huddle: the marker line every protocol message carries, so the receiving side knows it joined. ----

const ID = '[A-Za-z0-9_-]{1,80}'
const MARKER = new RegExp(`\\[huddle:(${ID}) leader:(${ID})\\]`)
const ADD_MARKER = new RegExp(`\\[huddle-add:(${ID}) ((?:${ID})(?:,${ID})*)\\]`)

export const huddleMarker = (id: string, leaderId: string) => `[huddle:${id} leader:${leaderId}]`
export const addMarker = (id: string, sessionIds: string[]) => `[huddle-add:${id} ${sessionIds.join(',')}]`

export function parseHuddleMarker(text: string): { id: string; leaderId: string } | null {
  const m = MARKER.exec(text)
  return m ? { id: m[1]!, leaderId: m[2]! } : null
}

export function parseAddMarker(text: string): { id: string; sessionIds: string[] } | null {
  const m = ADD_MARKER.exec(text)
  return m ? { id: m[1]!, sessionIds: m[2]!.split(',') } : null
}

/** The message without its machine lines, for the short copy a busy agent reads mid-turn. */
export const stripMarkers = (text: string): string =>
  text
    .split('\n')
    .filter(line => !MARKER.test(line) && !ADD_MARKER.test(line))
    .join('\n')
    .trim()

export const newHuddleId = (sessionId: string, now: number) => `${sessionId.slice(0, 8)}-${now}`

export const BACKGROUND_PREFIX = 'Background (from the session that started this one)'

/** What the session is "about": the start of what the person asked, never the text a parent session wrote to it. */
export function taskFromPrompt(text: string): string {
  const t = text.replace(/\s+/g, ' ').trim()
  return t.startsWith(BACKGROUND_PREFIX) ? '' : t.slice(0, 140)
}

/** The sidebar title is read on every tick for the first 8, then every 4th. */
export const shouldRefreshTitle = (tick: number): boolean => tick < 8 || tick % 4 === 0

// ---- Shell edits: which directories a command enters, and what changed in a repo while it ran. ----

type Word = { text: string; dynamic: boolean }

/** A shell line as lists of words, one list per simple command. Quotes and `~`/`$HOME` are resolved; a word that
 * needs the shell to expand (`$X`, backticks, globs) is flagged dynamic. */
function splitCommand(command: string, home: string): Word[][] {
  const cmds: Word[][] = [[]]
  let cur = ''
  let has = false
  let dynamic = false
  let quote = ''
  const push = () => {
    if (has) cmds[cmds.length - 1]!.push({ text: cur, dynamic })
    cur = ''
    has = false
    dynamic = false
  }
  const cut = () => {
    push()
    if (cmds[cmds.length - 1]!.length) cmds.push([])
  }
  const homeAt = (i: number): number => {
    for (const name of ['HOME', '{HOME}']) {
      const end = i + 1 + name.length
      if (command.startsWith(name, i + 1) && (name.startsWith('{') || !/[A-Za-z0-9_]/.test(command[end] ?? ''))) return end
    }
    return -1
  }
  for (let i = 0; i < command.length; i++) {
    const c = command[i]!
    if (quote === "'") {
      if (c === "'") quote = ''
      else cur += c
      continue
    }
    if (c === '$') {
      const end = home ? homeAt(i) : -1
      if (end > 0) {
        cur += home
        has = true
        i = end - 1
      } else {
        dynamic = true
        has = true
        cur += c
      }
      continue
    }
    if (quote === '"') {
      if (c === '"') quote = ''
      else if (c === '`') dynamic = true
      else if (c === '\\' && '"\\$`'.includes(command[i + 1] ?? ' ')) cur += command[++i]
      else cur += c
      continue
    }
    if (c === "'" || c === '"') {
      quote = c
      has = true
    } else if (c === '\\') {
      if (command[i + 1] === '\n') i++
      else if (i + 1 < command.length) {
        cur += command[++i]
        has = true
      }
    } else if (c === '#' && !has) {
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
    } else if (c === '~' && !has && home && (i + 1 >= command.length || /[/\s;&|)]/.test(command[i + 1]!))) {
      cur += home
      has = true
    } else if (c === '\n' || c === ';' || c === '|' || c === '&' || c === '(' || c === ')') cut()
    else if (c === ' ' || c === '\t' || c === '\r') push()
    else {
      if (c === '*' || c === '?' || c === '[' || c === '`') dynamic = true
      cur += c
      has = true
    }
  }
  push()
  return cmds.filter(c => c.length)
}

/** `p` against `base`, `.` and `..` folded, forward slashes: no file system involved. */
export function resolvePath(base: string, p: string): string {
  const abs = p.startsWith('/') || /^[A-Za-z]:[\\/]/.test(p)
  const full = slashes(abs || !base ? p : `${base}/${p}`)
  const prefix = /^([A-Za-z]:)?\//.exec(full)?.[0] ?? ''
  const stack: string[] = []
  for (const part of full.slice(prefix.length).split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') stack.pop()
    else stack.push(part)
  }
  return prefix + stack.join('/')
}

/** The directories a command names with `cd`, `pushd` and `git -C`, as absolute paths, in order. A `cd` moves
 * the directory the later parts of the line are read against. */
export function dirsInCommand(command: string, cwd: string, home = ''): string[] {
  const out: string[] = []
  const add = (d: string) => {
    if (d && !out.includes(d)) out.push(d)
  }
  let running = slashes(cwd)
  for (const words of splitCommand(command, slashes(home))) {
    let i = 0
    while (i < words.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(words[i]!.text)) i++
    const head = words[i]?.text
    if (head === 'cd' || head === 'pushd') {
      const arg = words.slice(i + 1).find(x => !x.text.startsWith('-'))
      if (arg && !arg.dynamic) {
        running = resolvePath(running, arg.text)
        add(running)
      }
    } else if (head === 'git') {
      let base = running
      for (let j = i + 1; j < words.length; j++) {
        const t = words[j]!
        if (t.text === '-C') {
          const dir = words[++j]
          if (dir && !dir.dynamic) {
            base = resolvePath(base, dir.text)
            add(base)
          }
        } else if (t.text === '-c') j++
        else if (!t.text.startsWith('-')) break
      }
    }
  }
  return out
}

/** `git status --porcelain=v1 -z` as path -> two-letter status. A rename lists its old path after the new one. */
export function parsePorcelain(out: string, cap = 2000): Record<string, string> {
  const map: Record<string, string> = {}
  const parts = out.split('\0')
  let count = 0
  for (let i = 0; i < parts.length && count < cap; i++) {
    const entry = parts[i]!
    if (entry.length < 4) continue
    const xy = entry.slice(0, 2)
    if (xy.includes('R') || xy.includes('C')) i++
    map[entry.slice(3)] = xy
    count++
  }
  return map
}

/** One repo's dirty files: git's status, and for some of them a signature of mtime and size. */
export type Snapshot = Record<string, { status: string; sig?: string }>

/** The paths that changed between two snapshots: a new status, a new signature, or not there before. A path that
 * left the list (committed, reverted) is not an edit. */
export function diffSnapshots(before: Snapshot, after: Snapshot): string[] {
  const changed: string[] = []
  for (const [path, a] of Object.entries(after)) {
    const b = before[path]
    if (!b || b.status !== a.status || (b.sig !== undefined && a.sig !== undefined && b.sig !== a.sig)) changed.push(path)
  }
  return changed.sort()
}

// ---- Huddle: who is in it, how the band reads it, who owns what. ----

export const ownerKey = (repoKey: string, rel: string) => `${repoKey}::${rel}`

/** The session the agreement gave this file to, if any. */
export const ownerOf = (lead: HuddleLead | undefined, repoKey: string, rel: string): string | undefined =>
  lead?.owners[ownerKey(repoKey, rel)]

/** The leader's presence: this session's own when it leads, else the peer's file. */
export function leaderOf(me: Presence, peers: Presence[]): Presence | null {
  const h = me.huddle
  if (!h) return null
  return h.leaderId === me.sessionId ? me : (peers.find(p => p.sessionId === h.leaderId) ?? null)
}

/** My huddle while it is live: its leader's presence is live, or another member was active in the last 4 h. */
export function liveHuddle(me: Presence, peers: Presence[], now: number): HuddleInfo | null {
  const h = me.huddle
  if (!h) return null
  if (h.leaderId === me.sessionId) return h
  const leader = peers.find(p => p.sessionId === h.leaderId)
  if (leader && isLive(leader, now)) return h
  const another = peers.some(
    p => p.sessionId !== me.sessionId && p.huddle?.id === h.id && !p.ended && now - p.lastActiveAt < FILE_WINDOW_MS,
  )
  return another ? h : null
}

/** Every session id in my live huddle (mine and the leader's included): who joined, plus whom the leader invited. */
export function huddleMembers(me: Presence, peers: Presence[], now: number): Set<string> | null {
  const h = liveHuddle(me, peers, now)
  if (!h) return null
  const ids = new Set<string>([me.sessionId, h.leaderId])
  for (const id of leaderOf(me, peers)?.huddle?.lead?.members ?? []) ids.add(id)
  for (const p of peers) if (p.huddle?.id === h.id) ids.add(p.sessionId)
  return ids
}

const who = (p: Presence): Who => ({
  title: p.title ?? '',
  task: p.task.slice(0, 60),
  hostId: isHostId(p.hostId) ? p.hostId : '',
})

/** Files a member edited after the agreement that the agreement gave to another member. */
export function ownerConflicts(lead: HuddleLead | undefined, members: Presence[], now: number): OwnerConflict[] {
  if (!lead?.agreedAt) return []
  const byId = new Map(members.map(m => [m.sessionId, m]))
  const found: { at: number; c: OwnerConflict }[] = []
  for (const editor of members) {
    for (const repo of Object.values(editor.repos)) {
      for (const [file, at] of Object.entries(repo.files)) {
        if (at <= lead.agreedAt! || now - at >= FILE_WINDOW_MS) continue
        const owner = byId.get(ownerOf(lead, repo.repoKey, file) ?? '')
        if (owner && owner.sessionId !== editor.sessionId) {
          found.push({ at, c: { editor: who(editor), owner: who(owner), repoName: repo.repoName, file } })
        }
      }
    }
  }
  return found.sort((a, b) => b.at - a.at).map(f => f.c)
}

/**
 * What the band shows. Peers that are live, not idle (unless their files clash) and share a repo are the ones to
 * speak of: if all of them are in my huddle it is one calm line, else the alert rows for those who are not.
 */
export function bandState(me: Presence, peers: Presence[], now: number): BandState {
  const alerts = assessAll(me, peers, now)
  const family = familyLine(me, peers, now)
  if (alerts.length === 0) return family ? { kind: 'family', family } : { kind: 'none' }
  const members = huddleMembers(me, peers, now)
  const outsiders = alerts.filter(a => !members?.has(a.sessionId))
  if (outsiders.length > 0) return { kind: 'alert', alerts: outsiders, hasHuddle: members !== null, ...(family ? { family } : {}) }

  const inAlert = new Set(alerts.map(a => a.sessionId))
  // A mother or a daughter takes no part in the huddle, even if a marker reached it.
  const others = peers.filter(
    p =>
      members!.has(p.sessionId) &&
      isLive(p, now) &&
      (!isIdle(p, now) || inAlert.has(p.sessionId)) &&
      !['mother', 'daughter'].includes(familyOf(me, p) ?? ''),
  )
  const h = me.huddle!
  const leader = leaderOf(me, peers)
  const confirmed =
    (h.leaderId === me.sessionId || h.ackAt ? 1 : 0) + others.filter(p => p.sessionId === h.leaderId || p.huddle?.ackAt).length
  return {
    kind: 'huddle',
    size: others.length + 1,
    confirmed,
    leader: leader ? who(leader) : { title: '', task: '', hostId: '' },
    leaderIsMe: h.leaderId === me.sessionId,
    conflicts: ownerConflicts(leader?.huddle?.lead, [me, ...others], now),
    ...(family ? { family } : {}),
  }
}

/** The live sessions of my family, for the dim line of the band; undefined when there are none. */
export function familyLine(me: Presence, peers: Presence[], now: number): Family | undefined {
  const mother = motherOf(me, peers, now)
  const daughters = peers.filter(p => p.sessionId !== me.sessionId && isLive(p, now) && familyOf(me, p) === 'daughter').length
  return mother || daughters ? { ...(mother ? { mother: who(mother) } : {}), daughters } : undefined
}

/** A repo's short name: the last part of its remote, or, with no remote (the key is its git directory), its folder. */
export function repoNameOf(repoKey: string, toplevel: string): string {
  const fromKey = repoKey.split('/').filter(Boolean).at(-1)?.replace(/\.git$/, '') ?? ''
  return fromKey || slashes(toplevel).split('/').filter(Boolean).at(-1) || toplevel
}

/** A huddle message cut to what a busy agent needs now: who, what clashes and how to answer. The protocol's later
 * points and the machine lines are left for the full message, which still arrives when the turn ends. */
export function compactForMidTurn(text: string, max = 1500): string {
  const lines = stripMarkers(text)
    .split('\n')
    .filter(line => !/^\s*[2-9]\.\s/.test(line))
  const out = lines.join('\n').trim()
  return out.length > max ? `${out.slice(0, max - 1)}…` : out
}

